INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('3fdc7efb-17d8-4575-8106-146953843f09', 'Era da Poeira', 49, 'ERA', NULL, 'O mundo vive um cenário pós-apocalíptico; a falta de recursos aproxima cada vez mais a sociedade de seu fim.', '2026-06-23 18:54:05.732025+00', '2026-06-23 18:54:05.732025+00', 'pt', 'ff3d5bed-6438-4fdb-8919-0a41250ff71e');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('93d9c0e6-e254-44ea-85ae-b703bcce06bd', 'Começa a Guerra dos Hexágonos', 50, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.742603+00', '2026-06-23 18:54:05.742603+00', 'pt', '659fdc07-604a-46b1-aa0e-133d7e54e5b8');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('cdaf8525-4ad7-4952-b93e-5fef4066aa0c', 'Era da Morte', 51, 'ERA', NULL, 'O mundo é assolado por conflitos constantes e marcha rumo ao seu fim.', '2026-06-23 18:54:05.914423+00', '2026-06-23 18:54:05.914423+00', 'pt', 'fd791fd4-6951-4fa8-957e-5979bff9427f');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b28c235a-0c6a-4b3d-9cf8-518eeec63559', 'Fim dos Mortais', 52, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.928631+00', '2026-06-23 18:54:05.928631+00', 'pt', 'f4f343d5-9208-45f9-b7d4-3debe69443da');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('36d5e2a5-be00-456b-bf11-113c0b737904', 'Era Primordial', 1, 'ERA', NULL, 'A era anterior à existência do mundo material — um tempo de pura essência, forças divinas e o alicerce sobre o qual toda a existência viria a ser construída. Nenhum mundo navegável existe aqui; apenas o infinito.', '2026-06-23 18:54:04.047617+00', '2026-06-24 02:31:11.341815+00', 'pt', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
INSERT INTO map_eras (map_id, era_id) VALUES ('omniverse', '36d5e2a5-be00-456b-bf11-113c0b737904');
INSERT INTO archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Comunicação', 'Terra', 'Ouros', 'Negócios', 'Extrovertido', 'Sentimento', 'Altruísta', 'A Comunicação pertence à Terra e aos Ouros, o arquétipo dos negócios — extrovertido, governado pelo sentimento e de natureza altruísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '4426f1f5-1f1f-433d-a35f-080a47ab4b32');
INSERT INTO archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Força', 'Fogo', 'Paus', 'Trabalho', 'Extrovertido', 'Sensação', 'Egoísta', 'A Força pertence ao Fogo e aos Paus, o arquétipo do trabalho — extrovertido, governado pela sensação e de natureza egoísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '594644a2-e7d2-41c8-91b3-f5c2789127f5');
INSERT INTO archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Astúcia', 'Ar', 'Espadas', 'Ofício', 'Introvertido', 'Razão', 'Egoísta', 'A Astúcia pertence ao Ar e às Espadas, o arquétipo do ofício — introvertido, governado pela razão e de natureza egoísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', '761d78d0-25cb-4b9b-9d6c-0d9b629f92c5');
INSERT INTO archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('60f946ab-4296-46cf-8fce-88011d8c62e2', 'Vontade', 'Água', 'Copas', 'Misticismo', 'Introvertido', 'Intuição', 'Altruísta', 'A Vontade pertence à Água e às Copas, o arquétipo do misticismo — introvertido, governado pela intuição e de natureza altruísta.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', 'd3116bc3-025c-4fa9-bb20-6f0c9cd9e2b6');
INSERT INTO archetypes (id, name, element, suit, vocation, temperament, cognitive_function, self_relation, description, created_at, updated_at, language, translation_group_id) VALUES ('21c3575b-4681-4d81-bcfb-97a07de3bd0a', 'Obsessão', NULL, NULL, NULL, NULL, NULL, NULL, 'A Obsessão está inteiramente fora da ordem quádrupla, não sendo regida por nenhum elemento ou naipe. Ela sustenta apenas a Fenda, o décimo terceiro signo, e o vazio que a Obsessão eternamente tenta preencher, e eternamente falha em fazê-lo.', '2026-06-25 01:30:07.075003+00', '2026-06-25 01:30:07.075003+00', 'pt', 'ac88b699-f67f-44d5-95e6-41a885a1343c');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('023f34b4-9899-473c-8ce7-2ceb6a3c858d', 'Os Anéis', 1, 'Fim da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Presença', 'Simboliza união e proteção.', 'Simboliza união e proteção. As pessoas do signo dos Anéis valorizam alianças, casamentos e conexão acima de tudo. Para elas, os outros não são apenas amigos ou familiares com quem interagem, mas uma extensão de si mesmas a ser protegida. Possuem uma beleza e um magnetismo naturais, oferecendo não apenas apoio emocional, mas também segurança física. Podem ser intimidadoras e impositivas com quem quer que ameace aqueles que amam, e raramente são alguém que se deseja provocar. Orgulham-se dessa reputação, exigindo demonstrações de apreço e cultivando sua imagem social. São amantes intensos que se ligam profundamente a seus amigos — uma proximidade que pode ser exigente em retorno. Ao mesmo tempo, são profundamente implacáveis com traidores ou com qualquer um que ataque sua imagem ou seus entes queridos. Costumam se estabelecer em papéis familiares comuns, mas também podem servir como protetores e guardiões leais.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '285857c0-7b67-48f2-9731-cc12c77efa40');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('eda70aa5-5de9-4013-a330-5849db9f0071', 'A Torre', 2, 'Início do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Forma', 'Simboliza resistência e robustez.', 'Simboliza resistência e robustez. Essas pessoas são executoras pragmáticas e confiantes — excelentes guardas, sentinelas ou soldados que confiam na própria força e cumprem tarefas sem questionar. A maioria dos da Torre segue alguma lei ou ordem, mantendo um senso de honra elevado, porém simples, defendendo a família, a nação, ou o que quer que considerem de igual valor. São trabalhadores e lutadores focados que buscam a perfeição em tudo o que fazem, e não relaxam até alcançá-la — após o que se orgulham de sua conquista e seguem em frente rumo a patamares mais altos. Este é um signo de pessoas ambiciosas, mas também pacientes e respeitosas. Querem poder, mas querem merecê-lo. Querem autoridade, mas jamais trairiam outrem para conquistá-la.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '83f9d998-0160-477e-8340-429f6106a86b');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('20bb7195-79d1-4039-9040-49225fe6f877', 'O Martelo', 3, 'Meio do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Poder', 'Representa a forma mais pura de honestidade e ambição.', 'Representa a forma mais pura de honestidade e ambição. Essas pessoas querem poder e não fazem segredo disso. Farão o que for necessário para obtê-lo, mas preferem manter tudo transparente — em suas mentes, já são as melhores, então não há necessidade de se esconder ou enganar. As pessoas do signo do Martelo são ferozmente competitivas. Preocupam-se pouco com os outros e favorecem abertamente um sistema em que apenas os melhores são recompensados. Não sentem vergonha de seu ofício e buscam os melhores resultados em qualquer campo em que se encontrem. Essa inquietação as torna excelentes trabalhadoras braçais ou lutadoras — brilham em qualquer atividade que exija esforço repetitivo ou exaustivo, construindo força com facilidade. Disciplinadas e rápidas para aprender, também são boas soldadas. O mundo é simples para uma pessoa do Martelo: ela não se detém em problemas profundos ou filosofia. Tudo o que importa é se tornar mais forte e mais poderosa do que era ontem. São apaixonadas e incontroláveis, entregando tudo de si naquilo que fazem. Quando felizes, riem alto. Quando irritadas, rugem como trovões.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '2468c5ea-8949-4f6d-8e3a-cb86e22de590');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('e10d0e63-f51a-4344-8a07-e2c877fc9378', 'O Capuz', 4, 'Fim do Verão', 'eb7ee58c-1c0a-4c67-ac53-f9616de9ea46', 'Habilidade', 'Representa a excelência da prática.', 'Representa a excelência da prática. As pessoas deste signo são ao mesmo tempo perspicazes e humildes. Buscam realização pessoal no mundo, procurando ser as melhores naquilo que fazem sem arrastar ninguém mais para essa busca. Sua luta é apenas contra si mesmas, e raramente a exibem abertamente. Ainda assim, tornam-se referências em seu campo e inevitavelmente atraem atenção. Não rejeitam a fama — ela é apenas mais uma ferramenta para sua ascensão —, mas também não se deleitam nela. O reconhecimento, para elas, é apenas mais um passo rumo à perfeição, que é a única recompensa verdadeira que buscam. Destacam-se como artistas marciais, atletas, atiradoras e outras praticantes de foco e precisão, nunca se cansando de refinar sua técnica. Por trás disso, são indivíduos astutos, levando sua perspicácia para suas personalidades, sempre medindo os outros contra si mesmas em suas mentes. Podem sentir inveja, mas raramente agem a partir dela — mais frequentemente, transformam essa admiração em motivação.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'ebd973da-6df0-4820-bb76-65fc71257329');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('54913dcc-d0e7-467b-b3d9-81d9059ebbc8', 'A Máscara', 5, 'Início do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Ardil', 'Simboliza inteligência e engenhosidade.', 'Simboliza inteligência e engenhosidade. São aqueles que encontram o caminho mais fácil. Desprezam o esforço e não veem virtude em tornar a vida mais difícil do que precisa ser. As pessoas do signo da Máscara podem ser encontradas enganando outros por meio de esquemas e golpes, mas podem igualmente ser mercadoras ou empresárias astutas que encontram brechas em qualquer sistema e lucram com elas. Não são necessariamente desonestas, mas são hábeis em trapaça e engano, possuindo um senso de moralidade flexível e um raciocínio rápido. Sob pressão, não hesitarão em dobrar o sistema e usar todos os meios necessários para melhorar sua situação. No entanto, em circunstâncias confortáveis, essas mesmas pessoas se tornam os aliados ou funcionários mais eficazes que se poderia pedir, já que valorizam sua posição e a recompensam na mesma moeda. A Máscara não é imune à culpa — simplesmente não se detém nela. Vê o mundo como o lugar difícil que ele é, acreditando que todos pisam em alguém para sobreviver, e não são exceção. Se não o fizerem, outro o fará — e, em sua visão, causam o menor dano possível ao longo do caminho. Tudo o que querem é uma vida melhor para si mesmas, não a ruína dos outros.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '889afafc-a095-461c-9e2c-1ae103591948');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('d1cf7fbe-5dd3-4c2e-86f5-b99b1fb976ec', 'A Lanterna', 6, 'Meio do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Visão', 'Representa orientação e sabedoria.', 'Representa orientação e sabedoria. As pessoas deste signo são as melhores professoras e as mais merecedoras de liderança, embora muitas vezes recusem posições de autoridade, sentindo-se indignas ou sem a ambição de reivindicá-las. São estrategistas talentosas que atraem seguidores naturalmente por meio de seu brilhantismo. Essas pessoas estão sempre enxergando além do que os outros veem — ponderando os problemas do mundo e buscando soluções para questões que a maioria nunca considera. Raramente, porém, agem sobre essas percepções; são muito melhores em apontar o caminho do que em percorrê-lo. Amam a filosofia e encontram prazer em viajar e explorar novos lugares, sempre em busca — na mente e no corpo — da verdade universal.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'f4ff1720-96c8-4736-80c0-9a05b02e3ea6');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('3e8b6e1a-b9e4-4e22-94b5-af36c6838738', 'A Lente', 7, 'Fim do Outono', 'f81901a4-9b9f-4fa1-8312-7c9671362d2a', 'Curiosidade', 'Representa a busca pelo conhecimento através do estudo.', 'Representa a busca pelo conhecimento através do estudo. As pessoas deste signo são os melhores artesãos e cientistas, hábeis em seguir métodos, explorar disciplinas e conceber soluções para todo tipo de problema. A Lente é pragmática por natureza, acreditando que o mundo possui uma ordem correta, e que segui-la é colocar as coisas nos eixos. Têm dificuldade em compreender opiniões ou mentalidades diferentes das suas. Tendem a ser altamente organizadas, arrumadas e autossuficientes, muitas vezes nunca se casando ou criando filhos. Embora tenham uma curiosidade profunda pelo que aprendem, não precisam de um raciocínio profundo por trás disso — contentam-se em saber como algo funciona sem precisar saber por quê. São também cuidadoras habilidosas de plantas, animais, edifícios e estruturas.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '49112518-7835-422c-9587-9d80060980c0');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('aa2cc57b-92c3-4a76-8e7d-9484a07c10d8', 'O Ouro', 8, 'Início do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Paixão', 'Representa talento e dom.', 'Representa talento e dom. As pessoas deste signo carregam um chamado para alguma habilidade altamente específica, que incorporam e executam com uma excelência que espanta a todos que a testemunham. São as melhores artífices, embora seu talento possa se manifestar em qualquer atividade. Isso não significa que dispensem treinamento — apenas que vivenciam seu treinamento como algo alegre e gratificante, e não como um trabalho exaustivo. As pessoas do signo do Ouro são calmas e corteses, raramente exibindo emoções fortes, e parecem manter tudo sob um controle silencioso. Fora de seu ofício, podem parecer inexpressivas — mas, uma vez engajadas com seu talento, tornam-se o centro das atenções quase instantaneamente. Podem cair na preguiça, já que tanto lhes vem com facilidade, mas se recusam a se tornar espetáculo ou experimento para quem as pressionar demais.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '96cc8ec0-0d3a-4119-8afa-d826b638ac30');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('24939216-46bd-4251-b3a9-f826c330aad4', 'O Cálice', 9, 'Meio do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Devoção', 'Representa devoção completa e altruísta.', 'Representa devoção completa e altruísta. As pessoas deste signo são vasos para algo maior que si mesmas — sacerdotisas perfeitas, ou simplesmente seguidoras perfeitas. Agem em nome de uma causa e derramam todo o seu ser nela, e os outros percebem uma pureza em suas ações, uma santidade em sua devoção. O Cálice é profundamente acolhedor, mas estranhamente vazio, como se não possuísse uma personalidade inteiramente própria. Raramente falam de suas próprias vidas ou lutas, mas, quando o fazem, é com reverência, graça e um otimismo inabalável. Aceitam o mundo como ele é, não buscando respostas nem soluções para ele, escolhendo em vez disso enfrentá-lo com paciência, guiando os outros rumo ao caminho de menor conflito. São sonhadoras, profundamente atraídas pelo oculto, dotadas de forte intuição — muitas vezes sentindo quando algo está prestes a dar certo ou errado — e propensas à superstição.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'a6675b83-ef16-49e5-878a-e0c5e7b823fa');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('48e68a23-0d30-4f46-8123-463f60daca4b', 'O Sino', 10, 'Fim do Inverno', '60f946ab-4296-46cf-8fce-88011d8c62e2', 'Afinação', 'Representa empatia e conexão.', 'Representa empatia e conexão. As pessoas deste signo compreendem e se conectam com as emoções alheias com facilidade, evocando sentimentos nos que as cercam sem esforço. Naturalmente sedutoras, podem ser tanto inspiradoras quanto perturbadoras. Embora muitas vezes distantes, são percebidas como afortunadas e fáceis de amar. Movem-se pela vida sem grandes ambições, e ainda assim as coisas sempre parecem se resolver a seu favor. Facilmente satisfeitas, não perseguem o refinamento, mas frequentemente o alcançam de qualquer forma, cercando-se de um esplendor que os outros invejam. Trabalham mal dentro de regras e sempre as testarão — não por rebeldia, mas como forma de expressão. Sentem o que os outros sentem e, sem querer, fazem os outros sentirem de forma diferente. Conseguem perceber mentiras e enganos, embora jamais consigam explicar como.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'b669a183-9c01-4a57-ba6d-389d97bb1ca8');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('8d339dcc-7405-4a2d-878b-fbfe7dd40820', 'O Espelho', 11, 'Início da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Persuasão', 'Representa manipulação e diplomacia em seu ápice.', 'Representa manipulação e diplomacia em seu ápice. As pessoas deste signo veem os outros como recursos, vivendo para influenciar e construir sua própria imagem. Naturalmente amistosas, elevam o moral dos que as cercam com facilidade, lendo e moldando comportamentos como lhes convém. Ideais como políticas, mercadoras, apostadoras ou espiãs. Não acreditam em verdade universal, sustentando em vez disso que tudo é questão de opinião — suas preferências são voláteis, importando-se pouco com qualquer resultado específico, desde que satisfaça a maioria. Podem ser profundamente indecisas, preferindo seguir a direção de outrem em assuntos complexos a escolher uma própria. Carecem de um senso de propósito pessoal, preenchendo essa ausência com os objetivos de seu grupo ou sociedade. Leem rostos e linguagem corporal como quem lê um livro aberto, e sabem precisamente como provocar ou seduzir.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', '0394b7de-e1bd-447e-9f38-faf24782c378');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('258c3c13-99d1-481e-8613-b36fd1ff188c', 'A Coroa', 12, 'Meio da Primavera', 'e5f9998b-cbfd-4e90-acd2-3d19adbe528e', 'Comunhão', 'Simboliza liderança e governo.', 'Simboliza liderança e governo. As pessoas deste signo são bem articuladas, valorizando a conexão interpessoal e a conversa acima da maioria das coisas — ideais como governantes e gestoras. Possuem um carisma natural e um dom para a oratória e o comando; quando falam, os outros escutam. Preocupam-se profundamente com a unidade e a solidariedade, e isso transparece em tudo o que fazem. Adoram coordenar grupos, inspirar motivação e direcionar os outros rumo ao caminho certo — embora nem sempre tenham certeza, elas mesmas, de qual seja esse caminho. Sempre projetam confiança e sempre parecem saber o que dizer, mesmo ao falar de assuntos que mal compreendem. A Coroa despreza a solidão e adora a rotina, raramente cessando seu trabalho e raramente viajando a menos que outros o desejem. Sentem pouco prazer em reuniões sociais, mas ainda assim comparecem, valorizando-as como oportunidades de conexão.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'cac54126-d160-41f6-aa93-da760505d57a');
INSERT INTO signs (id, name, sign_order, season_time, archetype_id, sub_archetype, summary, body, created_at, updated_at, language, translation_group_id) VALUES ('c523932f-bfea-4807-931b-4c90fc0f18e4', 'A Fenda', 13, 'Os dias fora de estação — aqueles que caem fora da contagem das quatro estações, os dias ‘excedentes’ do ano', '21c3575b-4681-4d81-bcfb-97a07de3bd0a', NULL, 'Marca um vazio no centro do próprio ser — um vazio que seus portadores passam a vida inteira tentando preencher, e nunca conseguirão.', 'Diz-se que, em certos dias e noites, uma pessoa pode nascer fora de qualquer um dos Doze Signos. Não é tarefa simples determinar qual hora exata, de qual dia exato, produzirá um filho da Fenda, pois sua influência se espalha tenuemente por todo o ano. E, ainda assim, eles nascem, e carregam uma natureza perturbada. A Fenda marca um vazio no centro do próprio ser — um vazio que passarão a vida inteira tentando preencher, e nunca conseguirão. Não possuem um senso real de sociedade, nem moral, nem motivação verdadeira. Buscarão tudo: atenção, elogio, valor e poder, mas jamais serão satisfeitos por qualquer um deles. Não se importam com emoção ou razão, com significado ou crescimento. Sempre provocarão destruição, seja tentando consumir tudo para si, seja reduzindo tudo ao seu redor ao mesmo vazio que eles próprios habitam. Aqueles nascidos sob a Fenda são vítimas tanto quanto são perigos — a serem abordados com cautela, mas também com compaixão. Sua fome infindável os impulsiona a níveis de habilidade sem igual entre os demais signos; sua disposição para o sacrifício pode levá-los mais longe do que qualquer outro poderia ir. São capazes de coisas extraordinárias, mas sempre operarão além dos limites naturais do mundo. Precisam ser detidos — e, ainda assim, que pena.', '2026-06-25 01:30:12.047656+00', '2026-06-25 01:30:12.047656+00', 'pt', 'bafd608a-31bd-48b3-bcb6-6ec61c42e5a4');
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('93944b42-d553-4cf1-9012-8bd6e4be7ac8', 'Omnia', 'A palavra final de todas as coisas, Omnia permanece na borda extrema do devir — deusa da totalidade, habitando uma perfeição que nenhum pensamento mortal jamais alcançou. Ela não é cultuada como uma entre tantas. É reconhecida como o limite que nenhum olho pode ver além, o ponto em que a existência cessa e o inimaginável começa.', '## Omnia
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('7e783887-2849-4b5c-a820-37ba88ab0370', 'Ani', 'Ani, o Primogênito e o Primordial, é o próprio deus da unidade — toda a existência comprimida numa única forma indivisível, sem gênero e absoluta. Não é abordado como um poder entre poderes, mas como a semente a partir da qual a divisão primeiro se tornou possível. Onde quer que ele ande, diz-se, o mundo lança raízes novamente em seu rastro.', 'Ani é o deus da unidade — da própria singularidade. É chamado o Primogênito, o Primordial, pois é a representação de toda a existência comprimida num único conceito indivisível. Ele é, a um só tempo, tudo e um: a totalidade do ser dobrada numa forma solitária.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('b5b92b46-4bc9-4e58-8ff7-31cfd77a19c1', 'Hexas', 'A deusa da União e da Proteção da Família, filha de Tetros. Onde seu pai suporta sozinho, Hexas traça o círculo que torna a separação desnecessária — a divindade do que resta depois que a paixão se assenta: a refeição compartilhada, o rosto familiar, a soleira cruzada em conjunto.', 'Hexas é a deusa do número seis, filha de Tetros. É a divindade da união e da proteção da família e dos entes queridos, e carrega o dom de seu pai para a resistência, sem seu isolamento. Onde Tetros permanece sozinho, imóvel, Hexas traça o círculo que torna a separação desnecessária. Seu símbolo é um hexágono cercado por círculos em cada vértice — cada nó distinto, cada um tocando dois outros, nenhum ponto deixado sem um vizinho.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('065056f3-c216-4548-bd46-05f6074183b7', 'Octo', 'O deus do Crescimento Eterno e da Evolução, filho de Tetros. Paciente onde seu pai é imóvel, Octo ensina que nada realmente cresce em linha reta — acumula-se, dobra-se sobre si mesmo e recomeça com mais do que tinha ao partir. Seu símbolo é o laço duplo: o caminho infinito que sempre retorna.', 'Octo é o deus do número oito, filho de Tetros. É a divindade do Crescimento Eterno e da Evolução — uma combinação que pode parecer se ajustar mal à natureza imóvel e estável de seu pai, até que se compreenda que o crescimento também pode ser paciente. Octo não se apressa. Não se lança. Ele acumula.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('745b6169-8df4-4025-bd80-9338394a4ffb', 'Enea', 'A deusa dos Mundos, dos Reinos e dos Planetas — uma das divindades de maior alcance. Enea não percebe valkani individuais; ela percebe civilizações. Percebe quando mundos se erguem e quando se apagam. Seu domínio é todo mundo que gira sob um sol.', 'Enea é a deusa do número nove, filha de Trios. É a divindade dos Mundos, dos Reinos e dos Planetas — de todo espaço vasto o bastante para conter multidões e complexo o bastante para sustentar sua própria história. É, por qualquer medida, uma das mais amplas divindades em pura extensão. O que ela guarda em seu domínio não é uma única terra ou um único povo, mas todo mundo que gira sob um sol.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('bac8cd6d-5515-47de-b4ce-a93464455ec4', 'Deca', 'A deusa da Completude e da Recompensa, filha de Tetros. Deca não concede presentes — ela os devolve. Aquilo que um valkani deu ao mundo em paciência, disciplina e esforço honesto, ela reflete de volta por inteiro. Seu julgamento é exato, e ela é a sensação de uma coisa, enfim, estar completa.', 'Deca é a deusa do número dez, filha de Tetros. É a divindade da Completude e da Recompensa — aquela que chega ao final das coisas, quando o trabalho está feito e as contas podem finalmente ser ajustadas. É, no sentido mais verdadeiro, a deusa do merecido.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('428801e6-e0be-485b-bc3d-ba2a87efcf3d', 'Imaws', 'Imaws é a metade executiva da união mais antiga da criação — o deus que dá forma àquilo que sua amada Ælime põe em movimento. Se ela é o impulso que deseja tornar-se, ele é a mão que o escreve em lei. Juntos geraram os Amets, os primeiros conceitos a vagar pela eternidade primordial, e de seus doze filhos escolhidos vieram todas as maravilhas e todas as feridas que o mundo viria a conhecer. O próprio Imaws mantém-se em lugares quietos e intocados — o coração de florestas antigas, o silêncio elevado das montanhas, o vão por trás de uma cachoeira — um homem de olhos cansados, cor de floresta, que vem escrevendo o mundo há mais tempo do que o mundo existe.', 'Abaixo de Omnia, ensina-se, desdobram-se um dohundred — cento e quarenta e quatro — camadas de céu celestial, e cada uma delas transborda de deuses indescritíveis: seres tão vastos e tão estranhos que nenhuma língua mortal jamais fixou um nome verdadeiro a um único deles, e cada um deles incompreensivelmente poderoso. E abaixo de tudo isso, mais fundo que o mais fundo desses dohundred céus, o alicerce sustenta apenas dois nomes: Imaws, e Ælime.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('e1ba55b5-5606-41dd-9532-f88875300e97', 'Ælime', 'Ælime é a metade motriz da união mais antiga da criação — a inquietação que deseja tornar-se, a centelha à qual Imaws, seu eterno contraponto, dá forma e lei. Sua beleza é exótica e impossivelmente inspiradora, e diz-se que um único vislumbre dela basta para erguer a alegria no coração de quem a vê; sua mente, igualmente notável, é capaz de desvendar qualquer problema e transformar qualquer caos em harmonia. Junto com Imaws, gerou os Amets, os primeiros conceitos a vagar pela eternidade primordial, e de seus doze filhos escolhidos vieram todas as maravilhas e todas as feridas que o mundo viria a conhecer. A própria Ælime é atraída para onde a vida se reúne mais alto — os litorais mais quentes, as cidades mais iluminadas, o festival mais concorrido — uma mulher de longos cabelos ruivos e cacheados, vestida com tanta delicadeza quanto deslumbramento, que tem sido o pulso sob o mundo desde antes de o mundo ter um pulso próprio.', 'Abaixo de Omnia, ensina-se, desdobram-se um dohundred — cento e quarenta e quatro — camadas de céu celestial, e cada uma delas transborda de deuses indescritíveis: seres tão vastos e tão estranhos que nenhuma língua mortal jamais fixou um nome verdadeiro a um único deles, e cada um deles incompreensivelmente poderoso. E abaixo de tudo isso, mais fundo que o mais fundo desses dohundred céus, o alicerce sustenta apenas dois nomes: Imaws, e Ælime.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('9f55b0ea-59fb-4ed9-b567-5ef28cdc5896', 'Aleph', 'O Deus da Consciência, primeiro entre os alephs e portador da Lanterna da Luz Verdadeira. Aquilo que a luz de sua lanterna toca é o que os valkani são capazes de perceber. Escolhido entre os doze Amets por Imaws e Ælime, ele permanece no centro da mitologia de Aniannoth na Era Primordial.', 'Entre todos os Amets, diz-se que nenhum é mais abençoado que Aleph. Muitos sustentam que ele foi o favorito entre os doze escolhidos de Imaws e Ælime. Por essa razão, diz-se, foi presenteado com a Lanterna da Luz Verdadeira. Outros chamam isso de opinião tendenciosa. Afirmam que todos os Amets foram agraciados em igual medida, e que a lanterna só nos parece o presente mais fino porque somos os únicos capazes de compreendê-la, enquanto os outros permanecem além do nosso alcance. Seja qual for a verdade, é certo que Aleph está entre os deuses mais importantes de toda a mitologia de Aniannoth. É, também, a figura no centro exato do conto que se desenrolou ao longo da Era Primordial.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('574c16bc-404e-4991-b9e4-df9ca774ab6a', 'Duo', 'Duo, o deus da Dualidade, é o filho primogênito de Ani e Zςanser — um ser dividido perfeitamente em dois, opostos em cor, temperamento e olhar, que empunha espadas gêmeas capazes de se unirem em uma só para cindir qualquer coisa em seu oposto perfeito.', 'Duo, o deus da Dualidade, assemelha-se muito a seu pai, Ani. Ele também se apresenta com serenidade, num estado de completude. Ele também contém ambos os gêneros em si. Ele também carrega a harmonia de todas as coisas.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('8fd5cc81-e6fd-430c-8755-267a68376c22', 'Pentos', 'O deus da Espiritualidade e da Religião, filho de Trios. Pentos responde quando os perdidos erguem os olhos e perguntam se algo os escuta — oferecendo não respostas, mas a capacidade de continuar buscando. Sua estrela de cinco pontas se estende a partir de um centro que não se move.', 'Pentos é o deus do número cinco, filho de Trios, e a encarnação divina da Espiritualidade e da Religião. É o guardião do sagrado — a força que responde quando os valkani, perdidos em corpo ou em alma, erguem os olhos e perguntam se algo os escuta. E algo, sempre, os escuta. Pentos irradia um poder que aqueles em sua presença acham difícil descrever depois. Ele não oprime. Ele ilumina. Seu símbolo é uma estrela de cinco pontas, cada braço se estendendo a partir de um centro que não se move.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('6aae628c-6e9c-4f02-9a4b-7b4ddbe120d7', 'Zςanser', 'Zςanser, muitas vezes chamada erroneamente de Deusa do Nada, é, na verdade, uma ausência — a única coisa que não pertence à totalidade de toda a existência. Habita num lago de água negra e gélida de sua própria criação, ao mesmo tempo afundando em suas profundezas e caminhando sobre sua superfície. Cinzenta e incolor, exceto por seus olhos verdes e cristalinos, ela é a matriz de potencial infinito da qual toda a criação é incessantemente esculpida, fugindo eternamente do fardo de ser drenada para dentro da existência.', 'Zςanser é, por vezes, e erroneamente, chamada de Deusa do Nada. Mas ela não é nada — ela é uma ausência, e até o nada pertence à totalidade de todas as coisas, ao passo que somente ela não pertence.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('6d40153a-701b-4ca8-9e03-c8c58d4ccc14', 'Tetros', 'O deus da Estabilidade e do Equilíbrio, presidindo sobre a saúde, a longevidade e a temperança. Eternamente sentado em lótus, Tetros estende sua bênção imutável apenas àqueles que se libertaram da compulsão de agarrar e conquistar. Seus quatro braços permanecem dobrados em meditação — não fraqueza, mas força que escolheu sua própria quietude.', 'Tetros é o deus da Estabilidade e do Equilíbrio. Preside sobre a saúde, sobre a longevidade e sobre a temperança — a arte silenciosa de saber quando o suficiente é suficiente. Encontra-se eternamente sentado na postura de lótus, imóvel como pedra, sólido como uma montanha que jamais precisou justificar seu próprio peso. Não pede nada daqueles que a ele se aproximam. Ele simplesmente persiste, e em sua persistência oferece apoio a todos que buscam a paz.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('38d1f0de-6024-4c54-a049-5923d15c9176', 'Trios', 'A divindade do Caos e do Movimento — a força inquieta que se recusa a deixar o mundo assentar-se em si mesmo. Trios sustenta que qualquer equilíbrio de opostos perfeitos gera apenas impasse, e que um terceiro elemento disruptivo é necessário para colocar a verdadeira evolução em movimento. Padroeiro das bestas e do instinto, carrega um tridente de bronze e três olhos, o terceiro dos quais percebe a realidade despida de toda ilusão.', 'Trios é a divindade do Caos e do Movimento. É a energia inquieta que desafia a estabilidade em favor da evolução — a força que se recusa a deixar o mundo assentar-se em si mesmo. Para os devotos de Trios, o conforto é uma maldição. Gera estagnação. Gera conformismo. Não é descanso, mas morte lenta.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('dc4b1793-26c5-4156-8823-1305012d0512', 'Hecta', 'A senhora da Magia e do Misticismo, filha de Trios. Ela aparece de forma diferente a cada um que a encontra, mas todo relato compartilha a mesma sensação: estar diante de algo imenso que poderia desfazer o ar ao redor. Ela não é cruel. Ela simplesmente é, e o mundo se organiza de acordo.', 'Hecta é a deusa do número sete, filha de Trios, e a senhora da Magia e do Misticismo. Aqueles que estudam o arcano pronunciam seu nome com cautela. Não exatamente por medo — embora o medo esteja presente —, mas pela consciência de que ela está escutando, de que ela é vasta, e de que a distância entre sua atenção e seu poder é muito pequena.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('aa6e8cb3-d753-4c2c-a4d5-af895620affe', 'Trixia', 'A sombra de Dixia e deusa da Imperfeição e da Particularidade. Onde sua irmã ergue o horizonte como destino, Trixia planta os pés no chão e se recusa a olhar tão longe — argumentando que a perfeição não é apenas inatingível, mas indesejável, pois algo absoluto e completo já cessou. E, ainda assim, em seu esforço incansável para contradizer Dixia, ela talvez tenha se tornado nada mais que a outra face da mesma moeda.', 'Trixia é a sombra de Dixia. É a deusa da Imperfeição e da Particularidade — a divindade que governa não sobre um reino idealizado ao fim de uma estrada, mas sobre o mundo como ele é encontrado: rachado, desigual e vivo. Onde sua irmã ergue o horizonte como destino, Trixia planta os pés no chão e se recusa a olhar tão longe.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('9107120d-9a87-42c0-bd4a-9fd85b7d7d27', 'Dixia', 'A deusa da Perfeição e da Harmonia, nascida da união de Trios e Tetros — do Caos e da Estabilidade, do Movimento e da Ordem. Ela não prega o perdão; ensina o diálogo e a compreensão, o trabalho paciente de devolver cada conflito ao seu princípio mais fundamental. A perfeição é seu destino, não seu lar: ela caminha à frente de seus seguidores na estrada, próxima o bastante para indicar o caminho, distante o bastante para não ser tocada.', 'Dixia é a deusa da Perfeição e da Harmonia. É, por sua própria natureza, um prodígio — um milagre que não deveria existir. Nasceu da união de Trios e Tetros: do Caos e da Estabilidade, do Movimento e da Ordem, das duas forças que pressionam uma contra a outra no alicerce de todas as coisas. E, ainda assim, daquele encontro, ela se ergueu. Não como um meio-termo entre elas, mas como prova de que sua aparente oposição jamais foi absoluta.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('9c5d0b20-7fcd-45a9-99f2-e3d926426979', 'Unixia', 'A deusa da União entre os Mundos Material e Espiritual, filha de Trios. Unixia não reconcilia os dois mundos — ela se move entre eles, e ao se mover torna o trânsito possível para os outros. Seus devotos são místicos e aqueles que roçaram algo que não puderam explicar, e a isso se estenderam.', 'Unixia é a deusa do número onze, filha de Trios. É a divindade da União entre os Mundos Material e Espiritual — a costura viva entre o que pode ser tocado e o que só pode ser sentido. Onze excede o familiar dez. Atravessa um limiar. E Unixia, nascida do caos e do movimento, é precisamente essa travessia.
INSERT INTO character_categories (character_id, category) VALUES ('93944b42-d553-4cf1-9012-8bd6e4be7ac8', 'DEITY');
