INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('acf5d45d-2163-4918-a4dd-eaac675ba44e', 'A Teosofia de Aniannoth', 'O arcabouço teológico fundado por sacerdotes eruditos que se recusaram a apenas acreditar. A Teosofia de Aniannoth classifica as entidades divinas pelos Conceitos que representam — dividindo os deuses em Externos, Verdadeiros e Valkani — reconhecendo, ainda assim, que nenhuma classificação pode conter por completo aquilo que descreve.', 'Nem todo sacerdote é um peregrino. Entre os incontáveis fiéis que repetem orações que jamais questionaram, que acendem velas sem curiosidade e invocam nomes que nunca examinaram, surge — raramente, em templos distantes dos centros de poder — um tipo diferente de mente. Não um devoto, mas um erudito. Não um seguidor, mas um estudioso do próprio ato de seguir. São essas as mentes que encaram a fé como encarariam qualquer outro fenômeno digno de compreensão: com rigor, com dúvida e com a disposição de nomear o que veem.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('1c1ec59c-99f8-4184-acc2-3a1725545080', 'Nós, Três Reis', 'A Triarquia de Trios é o modelo sagrado de governança ideal, dito ter sido estabelecido na cidade sagrada de Singisdônia sob a bênção de Trios. Três reis — o Alado, o Dourado e o Enraizado — encarnam, cada um, um eixo distinto do governo: futuro, presente e passado. Suas decisões são tomadas em uníssono, com dois votos sempre prevalecendo sobre um, garantindo que o reino jamais seja paralisado e que o interesse da maioria seja sempre preservado.', 'A Triarquia de Trios é a representação sagrada do governo ideal. Está escrito que a cidade sagrada de Singisdônia foi governada por três reis, cada um abençoado por sua vez pelo próprio Trios, e que todas as civilizações ainda por vir deveriam contemplar esse arranjo como a imagem do governo justo.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('7bbaa3f3-0029-4679-9ba7-4f1df291c98b', 'A Origem do Doze', 'A deusa Dixia governa o número doze — nascida da união de Trios e Tetros, caos e ordem, enganados rumo ao amor pela astúcia silenciosa de seu irmão Duo. Ela é a perfeição aritmética: divisível por cada ancestral de sua linhagem. De sua sombra, o número treze observa.', 'Entre todos os números dentro do infinito, nenhum é mais perfeito que o doze.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('91165b17-3214-40b5-bbf3-0f4432905570', 'Sobre a Palavra Deus', 'Uma investigação filosófica sobre o conceito de divindade — argumentando que a palavra deus é uma invenção valkani: um nome grande o bastante para conter tudo o que excede o alcance mortal, mas que nunca foi deles para dar.', 'Não há deus.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('a96e56ee-3b1e-46dd-90f0-2818379e3531', 'A Guerra pela Lanterna da Luz Verdadeira', 'Na Era Primordial, Z''Mthun — uma criatura de dimensões além do absoluto — declarou guerra contra Aleph para reclamar a Lanterna da Luz Verdadeira. Verum, o filho do meio de Aleph, ergueu-se em defesa, construiu a cidade sagrada de Singisdônia, consagrou doze cavaleiros e repeliu Z''Mthun. Verum tornou-se então Rei e Deus dos Alephs, e através de sua lanterna os valkani ganharam não apenas a contemplação, mas a capacidade de compreender o mundo.', 'Nem todos que a luz de Aleph toca são abençoados por ela. Zςanser, rainha do lago negro, ficou tão deslumbrada pela lanterna que sua luz a queimou, despertando-a de seu repouso eterno. O véu que a cobria, um presente de seus pais, mostrou-se incapaz de mantê-la oculta. Uma vez vulnerável, Zςanser tornou-se objeto de desejo cobiçoso entre os Alephs e outras criaturas da eternidade. Z''Mthun, uma besta terrível e adoradora da Deusa Ausente, então declarou guerra contra Aleph, buscando roubar sua lanterna. Diz-se que Z''Mthun era uma criatura de dimensões além do absoluto, moldada a partir de sombra e desespero. De seu corpo brotaram infindáveis soldados monstruosos — guerreiros-bestas, devoradores de deuses. Qualquer um deles sozinho poderia ter levado universos inteiros à ruína. Agora um exército inteiro marchava contra o Deus dos Alephs.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('a8032617-5a1b-4ff9-8f65-83f08333888f', 'Os Doze Signos Aélimicos', 'Uma ordem cosmológica, nomeada em homenagem a Ælime — deusa do amor, da inspiração e da ordem — que divide não apenas os povos nascidos sob ela, mas toda energia que percorre o universo, mortal e divina por igual. Quatro Arquétipos elementais se desdobram em doze Signos, cada um dado à forma viva em Singisdônia por um dos Doze Cavaleiros Originais. Um décimo terceiro Signo, a Fenda, permanece inteiramente fora dessa ordem — e mesmo assim reivindica um cavaleiro próprio.', 'A palavra Aélimico descende de Ælime, a deusa do amor, da inspiração e da ordem, pois sustenta-se que nenhuma divisão do mundo poderia jamais ser concebida sem antes se conceber a harmonia. Diz-se que a ordem de doze que ela revelou não apenas classifica os povos nascidos sob ela — classifica toda energia que percorre o universo, mortal e divina por igual. Aqueles que estudam suas origens afirmam que é quase tão antiga quanto a própria Omnia, e que a deusa Dixia se ergue como manifestação viva desse mesmo poder: o número dado a um rosto, a ordem dada ao sopro.
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('a4a55c04-a097-4350-82d2-b7b309c4d35a', 'A Última Oração', 'Um ensinamento preservado através de gerações da fé de Omnia — sobre aqueles que buscaram comunhão com a deusa e jamais foram vistos novamente, e a parábola contada nos templos para explicar o porquê.', '### A Parábola da Árvore Antiga
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('27ddff92-0140-42eb-889e-a0310f12ac92', 'O Chamado dos Doze Amets', 'O mito de como os primeiros conceitos vieram a vagar pela eternidade primordial, e do único pedido — feito por Imaws e Ælime a doze de seus próprios filhos — que colocou toda a trama do universo em movimento, para o bem e para um mal muito maior.', 'Os Amets
INSERT INTO lore (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id, language, translation_group_id) VALUES ('8986dc8b-69b3-4f61-bfac-1036d3ffba60', 'Sexualidade dos Deuses', 'Um relato filosófico sobre a natureza divina: os deuses de Aniannoth são conceitos tornados soberanos, não corpos. Não carregam gênero, não são vinculados a nenhuma convenção matrimonial, e geram descendência através da colisão de princípios vivos — ou apenas de sua própria substância.', 'Os deuses de Aniannoth são mais comumente retratados em formas que se assemelham aos valkani — dois olhos, duas mãos, um corpo que se ergue e respira. Mas essa semelhança é uma conveniência, não uma verdade. A forma antropomórfica é um vaso escolhido pela legibilidade, uma forma que a mente mortal pode conter sem se fraturar. Os próprios deuses não são corpos. São conceitos tornados soberanos. São princípios anteriores à matéria da qual a carne é composta.
